+fn finish_notes(path: &mut Toolpath, local: &[Triangle], r: f64, d: f64, bottom: f64, tol: f64, under: bool) {
+    let gaps = gaps::unreached(local, &Cover::of(path, r, d + tol), r, bottom, tol);
