+/// a feed across the part.
+fn kept(base: &Toolpath, keeps: &dyn Fn(Point3) -> bool, step: f64) -> Toolpath {
+    let mut out: Vec<Move> = Vec::with_capacity(base.moves.len());
+    let mut cut_end: Option<Point3> = None;
