+    }
+    let n = ((len / step).ceil() as usize).clamp(1, 4096);
+    let at = |i: usize| {
+        let t = i as f64 / n as f64;
+        Point3::new(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t, a.z + (b.z - a.z) * t)
